const req = $input.first().json.body || $input.first().json;

const units = Number(req.unitsToRedeem || 10);
const nav = Number(req.nav || 100);
const grossAmount = Number((units * nav).toFixed(2));
const exitLoadApplied = Number((grossAmount * 0.01).toFixed(2));
const netRedemptionAmount = Number((grossAmount - exitLoadApplied).toFixed(2));

return {
  json: {
    success: true,
    intent: 'WEALTH',
    subIntent: 'REDEMPTION_SIMULATION',
    mode: 'SIMULATION',
    disclaimer: 'This is a simulated redemption. No real monetary transaction occurred.',
    data: {
      userId: req.userId,
      fundId: req.fundId,
      unitsRedeemed: units,
      nav,
      grossAmount,
      exitLoadApplied,
      netRedemptionAmount,
      mode: 'SIMULATION',
      status: 'Completed',
      transactionDate: new Date().toISOString()
    },
    timestamp: new Date().toISOString()
  }
};
